using System;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
namespace DesktopTodo {
 public static class DateRules {
  public static bool TryDate(string text,out DateTime? value){value=null;if(string.IsNullOrWhiteSpace(text))return true;DateTime parsed;if(!Regex.IsMatch(text,"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")||!DateTime.TryParseExact(text,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed))return false;value=parsed.Date;return true;}
  public static bool TryReminder(string text,out string value){value="";if(string.IsNullOrWhiteSpace(text))return true;DateTime parsed;if(!DateTime.TryParseExact(text.Trim(),new[]{"yyyy-MM-dd HH:mm","yyyy-MM-ddTHH:mm"},CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed))return false;value=parsed.ToString("yyyy-MM-ddTHH:mm");return true;}
  public static void Verify(){DateTime? d;if(TryDate("1",out d)||TryDate("11",out d)||TryDate("2026-02-30",out d)||TryDate("2026-13-01",out d)||TryDate("2026-1-2",out d)||!TryDate("2028-02-29",out d)||!TryDate("",out d))throw new Exception("Strict date validation failed");string reminder;if(TryReminder("9",out reminder)||TryReminder("2026-11-01 25:00",out reminder)||!TryReminder("2026-11-01 09:00",out reminder))throw new Exception("Reminder validation failed");}
 }
 public class StrictDateInput:Grid {
  readonly TextBox input;readonly Popup popup;DateTime month=new DateTime(DateTime.Today.Year,DateTime.Today.Month,1);
  public string Text {get{return input.Text;}set{input.Text=value??"";}}
  public DateTime? SelectedDate {get{DateTime? value;return DateRules.TryDate(Text,out value)?value:null;}set{Text=value.HasValue?value.Value.ToString("yyyy-MM-dd"):"";}}
  public StrictDateInput(){ColumnDefinitions.Add(new ColumnDefinition());ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(34)});Margin=new Thickness(0,6,0,12);input=Design.Input();input.Margin=new Thickness(0);input.ToolTip="연-월-일 형식으로 입력하세요. 예: 2026-11-01";Children.Add(input);var button=new Button{Content="▦",Width=30,Height=34,Margin=new Thickness(4,0,0,0),Background=UI.Color("#2A2D35"),Foreground=Design.Ink,ToolTip="달력에서 날짜 선택",Cursor=System.Windows.Input.Cursors.Hand};Grid.SetColumn(button,1);Children.Add(button);popup=new Popup{PlacementTarget=this,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true};button.Click+=(o,e)=>{var date=SelectedDate??DateTime.Today;month=new DateTime(date.Year,date.Month,1);BuildCalendar();popup.IsOpen=true;};Unloaded+=(o,e)=>popup.IsOpen=false;}
  internal void VerifyCalendarSelection(){Children.OfType<Button>().Single().RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var days=((StackPanel)((Border)popup.Child).Child).Children.OfType<UniformGrid>().Single();days.Children.OfType<Button>().First(b=>Convert.ToString(b.Content)=="15").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(popup.IsOpen||SelectedDate!=new DateTime(month.Year,month.Month,15))throw new Exception("Calendar date selection failed");}
  void BuildCalendar(){var panel=new StackPanel{Width=266};var header=new DockPanel{Margin=new Thickness(0,0,0,8)};Button previous=Design.Button("‹",()=>{month=month.AddMonths(-1);BuildCalendar();}),next=Design.Button("›",()=>{month=month.AddMonths(1);BuildCalendar();});previous.Tag=next.Tag="date-control";previous.Width=next.Width=32;DockPanel.SetDock(previous,Dock.Left);DockPanel.SetDock(next,Dock.Right);header.Children.Add(previous);header.Children.Add(next);var title=Design.Text(month.ToString("yyyy년 M월"),14);title.HorizontalAlignment=HorizontalAlignment.Center;header.Children.Add(title);panel.Children.Add(header);var days=new UniformGrid{Columns=7};foreach(var name in new[]{"일","월","화","수","목","금","토"})days.Children.Add(new TextBlock{Text=name,Foreground=Design.Muted,TextAlignment=TextAlignment.Center,FontSize=11});var first=month.AddDays(-(int)month.DayOfWeek);for(int i=0;i<42;i++){var date=first.AddDays(i);var day=date;var b=new Button{Content=date.Day.ToString(),Height=30,Margin=new Thickness(1),Foreground=date.Month==month.Month?Design.Ink:Design.Muted,Background=SelectedDate==date?Design.Teal:Brushes.Transparent,ToolTip=date.ToString("yyyy-MM-dd")};if(SelectedDate==date)b.Foreground=Design.Paper;b.Click+=(o,e)=>{SelectedDate=day;popup.IsOpen=false;};days.Children.Add(b);}panel.Children.Add(days);var clear=Design.Button("마감일 없음",()=>{SelectedDate=null;popup.IsOpen=false;});clear.Tag="date-control";clear.Width=double.NaN;clear.Margin=new Thickness(0,8,0,0);panel.Children.Add(clear);popup.Child=new Border{Child=panel,Background=Design.Paper,BorderBrush=UI.Color("#414651"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(14),Padding=new Thickness(12)};}
 }
}
